class DeprecationNoticeMiddleware:
    def __init__(self, get_response):
        self.get_response = get_response

    def __call__(self, request):
        response = self.get_response(request)

        # اگر درخواست به v1 بود، هدر هشدار اضافه کن
        if request.path.startswith("/api/v1/"):
            response["Deprecation"] = "true"
            response["Sunset"] = "Sat, 31 Dec 2025 23:59:59 GMT"
            response["Link"] = '</api/v2/>; rel="successor-version"'
            response["Warning"] = '299 - "Deprecated API. Use /api/v2/ instead."'

        return response
